using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.FNZ.TiposMovimiento{    [SwaggerSchema("Modelo de lectura de un TiposMovimiento")]    [GraphQLDescription("Objeto que representa un TiposMovimiento existente.")]    public class clReadTiposMovimiento    {        [SwaggerSchema("Identificador único del TiposMovimiento")]        [GraphQLDescription("Identificador único del TiposMovimiento")]        public int? TipoMovimientoID { get; set; }        [SwaggerSchema("TipoMovimiento")]        [GraphQLDescription("TipoMovimiento")]        public string? TipoMovimiento { get; set; } = default!;        [SwaggerSchema("bCargo")]        [GraphQLDescription("bCargo")]        public bool? bCargo { get; set; }        [SwaggerSchema("bAbono")]        [GraphQLDescription("bAbono")]        public bool? bAbono { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TiposMovimiento")]    [GraphQLDescription("Input para crear un TiposMovimiento.")]    public class clCreateTiposMovimiento    {        [GraphQLNonNullType] [SwaggerSchema("TipoMovimiento")]        [GraphQLDescription("TipoMovimiento")]        public string TipoMovimiento { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bCargo")]        [GraphQLDescription("bCargo")]        public bool bCargo { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bAbono")]        [GraphQLDescription("bAbono")]        public bool bAbono { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TiposMovimiento")]    [GraphQLDescription("Input para actualizar parcialmente un TiposMovimiento.")]    public class clUpdateTiposMovimiento    {        [SwaggerSchema("Identificador único del TiposMovimiento")]        [GraphQLDescription("Identificador único del TiposMovimiento")]        public int? TipoMovimientoID { get; set; }        [SwaggerSchema("TipoMovimiento")]        [GraphQLDescription("TipoMovimiento")]        public string? TipoMovimiento { get; set; }        [SwaggerSchema("bCargo")]        [GraphQLDescription("bCargo")]        public bool? bCargo { get; set; }        [SwaggerSchema("bAbono")]        [GraphQLDescription("bAbono")]        public bool? bAbono { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}